INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist ein Klassendiagramm nur für Softwareentwickler relevant?', 2, '[{"text": "Nein", "correct": true, "because": "Auch für Analysten und Architekten nützlich"}, {"text": "Ja", "correct": false, "because": "Breitere Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit einem Klassendiagramm?', 3, '[{"text": "Klassenstruktur visualisieren", "correct": true, "because": "Zeigt Klassen und Beziehungen"}, {"text": "Datenfluss darstellen", "correct": false, "because": "Datenflussdiagramm-Thema"}, {"text": "Hardware planen", "correct": false, "because": "Verteilungsdiagramm"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente gehören zu einem Klassendiagramm?', 5, '[{"text": "Klassen", "correct": true, "because": "Grundbausteine"}, {"text": "Beziehungen", "correct": true, "because": "Verbinden Klassen"}, {"text": "Farbanimation", "correct": false, "because": "Irrelevant"}, {"text": "Prozessfluss", "correct": false, "because": "Aktivitätsdiagramm"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Klassendiagramme zeigen Attribute. b) Sie ersetzen Sequenzdiagramme.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Sequenz für Abläufe"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei einem Klassendiagramm?', 4, '[{"text": "Klassenattribute", "correct": false, "because": "Beschreiben Klassen"}, {"text": "Beziehungen", "correct": false, "because": "Zeigen Verknüpfungen"}, {"text": "Hardwarezuordnung", "correct": true, "because": "Verteilungsdiagramm"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Klassendiagramm auch Methoden zeigt?', 2, '[{"text": "Ja", "correct": true, "because": "Methoden sind Teil der Klasse"}, {"text": "Nein", "correct": false, "because": "Nicht nur Attribute"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Symbol wähle ich für eine Klasse?', 3, '[{"text": "Rechteck", "correct": true, "because": "UML-Standard"}, {"text": "Pfeil", "correct": false, "because": "Nur Beziehungen"}, {"text": "Kreis", "correct": false, "because": "Andere Diagramme"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Beziehungen gehören zu einem Klassendiagramm?', 5, '[{"text": "Vererbung", "correct": true, "because": "Hierarchie zeigen"}, {"text": "Assoziation", "correct": true, "because": "Verknüpfungen darstellen"}, {"text": "Datenfluss", "correct": false, "because": "Datenflussdiagramm"}, {"text": "Farbschema", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Klassendiagramme sind statisch. b) Sie zeigen Hardwarezuordnung. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Hardware ist Verteilungsdiagramm"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für ein Klassendiagramm?', 4, '[{"text": "Klassen", "correct": false, "because": "Kern der Darstellung"}, {"text": "Beziehungen", "correct": false, "because": "Verbinden Klassen"}, {"text": "Prozessschritte", "correct": true, "because": "Aktivitätsdiagramm"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist ein Klassendiagramm nur für große Projekte?', 2, '[{"text": "Nein", "correct": true, "because": "Auch kleine Projekte profitieren"}, {"text": "Ja", "correct": false, "because": "Skalierung unabhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Informationen zeigt ein Klassendiagramm?', 4, '[{"text": "Klassenattribute", "correct": true, "because": "Beschreiben Eigenschaften"}, {"text": "Methoden", "correct": true, "because": "Definieren Verhalten"}, {"text": "Ablaufsequenzen", "correct": false, "because": "Sequenzdiagramm"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Klassendiagramme dynamische Abläufe zeigen. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Statische Struktur"}, {"text": "Ja", "correct": false, "because": "Dynamik in anderen Diagrammen"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei einem Klassendiagramm?', 3, '[{"text": "Klarheit der Struktur", "correct": true, "because": "Fördert Verständnis"}, {"text": "Schnelle Erstellung", "correct": false, "because": "Qualität zählt"}, {"text": "Technische Details", "correct": false, "because": "Abstraktion im Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Klassendiagramme zeigen Vererbung. b) Sie sind für Hardwareplanung wichtig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Hardware ist Verteilungsdiagramm"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ein Klassendiagramm?', 5, '[{"text": "Strukturübersicht", "correct": true, "because": "Klarheit über Klassen"}, {"text": "Beziehungsplanung", "correct": true, "because": "Verknüpfungen sichtbar"}, {"text": "Datenflussanalyse", "correct": false, "because": "Datenflussdiagramm"}, {"text": "Hardwarezuordnung", "correct": false, "because": "Verteilungsdiagramm"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei einem Klassendiagramm unwichtig?', 3, '[{"text": "Klassenmethoden", "correct": false, "because": "Definieren Verhalten"}, {"text": "Beziehungsarten", "correct": false, "because": "Struktur zeigen"}, {"text": "Blinkende Anzeige", "correct": true, "because": "Kein Strukturfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Zeigt ein Klassendiagramm auch Instanzen?', 3, '[{"text": "Nein", "correct": true, "because": "Instanzen sind Objektdiagramm"}, {"text": "Ja", "correct": false, "because": "Fokus auf Struktur"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Klassendiagramm für Tests hilft?', 2, '[{"text": "Ja", "correct": true, "because": "Struktur für Testplanung"}, {"text": "Nein", "correct": false, "because": "Testfälle ableitbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Symbol wähle ich für eine Vererbung?', 4, '[{"text": "Pfeil mit leerem Dreieck", "correct": true, "because": "UML-Standard"}, {"text": "Gefüllter Pfeil", "correct": false, "because": "Andere Bedeutung"}, {"text": "Kreis", "correct": false, "because": "Andere Diagramme"}]');
